from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    distinct_strings = []
    current_string = ""
    open_count = 0

    for char in paren_string:
        if char == '(':
            open_count += 1
            if open_count == 1:
                current_string += char
        elif char == ')':
            open_count -= 1
            if open_count == 0:
                current_string += char
                distinct_strings.append(current_string)
                current_string = ""
        else:
            if open_count > 0:
                current_string += char

    return distinct_strings

